import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_triplet_loss_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
template<int BLOCK_SIZE, bool VEC4>
__global__ void triplet_margin_mean_kernel(const float* __restrict__ anchor,
                                           const float* __restrict__ positive,
                                           const float* __restrict__ negative,
                                           float* __restrict__ out,
                                           int64_t B,
                                           int64_t D,
                                           float margin,
                                           float eps) {
    int i = blockIdx.x;
    if (i >= B) return;
    extern __shared__ float shared[];
    const int WARPS = (BLOCK_SIZE + 31) / 32;
    float* s1 = shared;                  // partial sums for positive distance (per-warp)
    float* s2 = shared + WARPS;          // partial sums for negative distance (per-warp)
    float sum1 = 0.0f;
    float sum2 = 0.0f;
    int64_t base = static_cast<int64_t>(i) * D;
    if (VEC4) {
        // Vectorized path with unrolling: requires D % 4 == 0
        int64_t vecD = D >> 2; // number of float4 elements
        const float4* __restrict__ a4 = reinterpret_cast<const float4*>(anchor + base);
        const float4* __restrict__ p4 = reinterpret_cast<const float4*>(positive + base);
        const float4* __restrict__ n4 = reinterpret_cast<const float4*>(negative + base);
        for (int64_t j4 = threadIdx.x; j4 < vecD; j4 += BLOCK_SIZE * 4) {
            #pragma unroll
            for (int ui = 0; ui < 4; ++ui) {
                int64_t idx = j4 + static_cast<int64_t>(ui) * BLOCK_SIZE;
                if (idx < vecD) {
                    float4 av = a4[idx];
                    float4 pv = p4[idx];
                    float4 nv = n4[idx];
                    float dpx = av.x - pv.x; float dnx = av.x - nv.x;
                    float dpy = av.y - pv.y; float dny = av.y - nv.y;
                    float dpz = av.z - pv.z; float dnz = av.z - nv.z;
                    float dpw = av.w - pv.w; float dnw = av.w - nv.w;
                    sum1 += dpx*dpx + dpy*dpy + dpz*dpz + dpw*dpw;
                    sum2 += dnx*dnx + dny*dny + dnz*dnz + dnw*dnw;
                }
            }
        }
    } else {
        // Scalar path with unrolling
        for (int64_t j = threadIdx.x; j < D; j += BLOCK_SIZE * 4) {
            #pragma unroll
            for (int ui = 0; ui < 4; ++ui) {
                int64_t idx = j + static_cast<int64_t>(ui) * BLOCK_SIZE;
                if (idx < D) {
                    float a = anchor[base + idx];
                    float p = positive[base + idx];
                    float n = negative[base + idx];
                    float dp = a - p;
                    float dn = a - n;
                    sum1 += dp * dp;
                    sum2 += dn * dn;
                }
            }
        }
    }
    // Warp-level reduction
    unsigned int mask = 0xffffffffu;
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;  // warp id within the block
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum1 += __shfl_down_sync(mask, sum1, offset);
        sum2 += __shfl_down_sync(mask, sum2, offset);
    }
    if (lane == 0) {
        s1[wid] = sum1;
        s2[wid] = sum2;
    }
    __syncthreads();
    float block_sum1 = 0.0f;
    float block_sum2 = 0.0f;
    if (wid == 0) {
        if (lane < WARPS) {
            block_sum1 = s1[lane];
            block_sum2 = s2[lane];
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            block_sum1 += __shfl_down_sync(mask, block_sum1, offset);
            block_sum2 += __shfl_down_sync(mask, block_sum2, offset);
        }
        if (lane == 0) {
            float dpos = sqrtf(block_sum1 + eps);
            float dneg = sqrtf(block_sum2 + eps);
            float l = dpos - dneg + margin;
            if (l < 0.0f) l = 0.0f;
            atomicAdd(out, l / (float)B);
        }
    }
}
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                       torch::Tensor positive,
                                       torch::Tensor negative,
                                       double margin,
                                       double eps) {
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");
    TORCH_CHECK(anchor.scalar_type() == at::ScalarType::Float, "Only float32 supported for anchor");
    TORCH_CHECK(positive.scalar_type() == at::ScalarType::Float, "Only float32 supported for positive");
    TORCH_CHECK(negative.scalar_type() == at::ScalarType::Float, "Only float32 supported for negative");
    TORCH_CHECK(anchor.numel() > 0, "Empty anchor tensor");
    TORCH_CHECK(anchor.sizes() == positive.sizes(), "anchor and positive must have the same shape");
    TORCH_CHECK(anchor.sizes() == negative.sizes(), "anchor and negative must have the same shape");
    TORCH_CHECK(anchor.size(0) >= 1, "Expected shape [B, ...] with B >= 1");
    auto a = anchor.contiguous().view({anchor.size(0), -1});
    auto p = positive.contiguous().view({positive.size(0), -1});
    auto n = negative.contiguous().view({negative.size(0), -1});
    const int64_t B = a.size(0);
    const int64_t D = a.size(1);
    auto out = torch::zeros({}, a.options());
    constexpr int BLOCK = 256;
    dim3 block(BLOCK);
    dim3 grid(B);
    size_t shmem = 2 * ((BLOCK + 31) / 32) * sizeof(float);
    if ((D & 3LL) == 0) {
        triplet_margin_mean_kernel<BLOCK, true><<<grid, block, shmem, at::cuda::getCurrentCUDAStream()>>>(
            a.data_ptr<float>(),
            p.data_ptr<float>(),
            n.data_ptr<float>(),
            out.data_ptr<float>(),
            B,
            D,
            static_cast<float>(margin),
            static_cast<float>(eps)
        );
    } else {
        triplet_margin_mean_kernel<BLOCK, false><<<grid, block, shmem, at::cuda::getCurrentCUDAStream()>>>(
            a.data_ptr<float>(),
            p.data_ptr<float>(),
            n.data_ptr<float>(),
            out.data_ptr<float>(),
            B,
            D,
            static_cast<float>(margin),
            static_cast<float>(eps)
        );
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUDA kernel launch failed: ", cudaGetErrorString(err));
    return out;
}
"""

binding_src = r"""
#include <torch/extension.h>
// Forward declaration of the CUDA function implemented in the .cu source
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                       torch::Tensor positive,
                                       torch::Tensor negative,
                                       double margin,
                                       double eps);
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("triplet_margin_loss_cuda",
        &triplet_margin_loss_cuda,
        "Triplet margin loss (CUDA, fused)");
}
"""
_triplet_loss_ext = load_inline(
    name="triplet_margin_loss_ext",
    cpp_sources=[binding_src],
    cuda_sources=[_triplet_loss_cuda_src],
    with_cuda=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks using a single fused CUDA kernel.
    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6

    def forward(self, anchor, positive, negative):
        # Move inputs to CUDA and ensure dtype/contiguity
        orig_device = anchor.device
        # Ensure same device
        if not anchor.is_cuda or not positive.is_cuda or not negative.is_cuda:
            anchor = anchor.to('cuda', dtype=torch.float32, non_blocking=False)
            positive = positive.to('cuda', dtype=torch.float32, non_blocking=False)
            negative = negative.to('cuda', dtype=torch.float32, non_blocking=False)
        else:
            anchor = anchor.contiguous().to(dtype=torch.float32)
            positive = positive.contiguous().to(dtype=torch.float32)
            negative = negative.contiguous().to(dtype=torch.float32)

        # Shape and size checks are done in the CUDA function as well
        out = _triplet_loss_ext.triplet_margin_loss_cuda(anchor, positive, negative, self.margin, self.eps)

        # Return result on the original device of anchor for compatibility
        if orig_device.type != 'cuda':
            out = out.to(orig_device)
        return out


# Keep the original input generation helpers
batch_size = 32768
input_shape = (8192,)
dim = 1

def get_inputs():
    scale = torch.rand(())
    return [torch.rand(batch_size, *input_shape)*scale, torch.rand(batch_size, *input_shape), torch.rand(batch_size, *input_shape)]

def get_init_inputs():
    return [1.0]  # Default margin

